INSERT INTO `surveys_task_skenario` (`id`, `task_skenario`, `description`, `id_survei`, `created_at`) VALUES
(5, 'Login', '<p>\r\n </p><p></p><p></p><ol><li><span style=\"font-size:10.0pt;line-height:150%;\r\nfont-family:\"Times New Roman\",serif;mso-fareast-font-family:\"Times New Roman\";\r\nmso-ansi-language:IN;mso-fareast-language:JA;mso-bidi-language:AR-SA\">Buka\r\nAplikasi HoYoLAB</span></li><li><span style=\"font-size:10.0pt;line-height:150%;\r\nfont-family:\"Times New Roman\",serif;mso-fareast-font-family:\"Times New Roman\";\r\nmso-ansi-language:IN;mso-fareast-language:JA;mso-bidi-language:AR-SA\"><span style=\"font-size: 10pt; line-height: 150%;\">Pilih\r\nmetode login berdasarkan akun game dan akun HoYoLAB yang sudah terkait</span></span></li><li><span style=\"font-size:10.0pt;line-height:150%;\r\nfont-family:\"Times New Roman\",serif;mso-fareast-font-family:\"Times New Roman\";\r\nmso-ansi-language:IN;mso-fareast-language:JA;mso-bidi-language:AR-SA\"><span style=\"font-size: 10pt; line-height: 150%;\"><span style=\"font-size: 10pt; line-height: 150%;\">Ceklist\r\nbox persetujuan persyaratan.</span></span></span></li><li><span style=\"font-size:10.0pt;line-height:150%;\r\nfont-family:\"Times New Roman\",serif;mso-fareast-font-family:\"Times New Roman\";\r\nmso-ansi-language:IN;mso-fareast-language:JA;mso-bidi-language:AR-SA\"><span style=\"font-size: 10pt; line-height: 150%;\"><span style=\"font-size: 10pt; line-height: 150%;\"><span style=\"font-size: 10pt; line-height: 150%;\">Selesai</span></span></span></span></li></ol>', 11, '2025-06-07 04:53:58'),
(6, 'Mencari Artikel dan Melakukan Komentar.', '<p>Silahkan ada lakukan pencarian artikel pada menu beranda/home kemudian lakukan komentar pada postingan.</p>', 11, '2025-05-29 01:54:52'),
(7, 'Claim Daily check-in', '<p>1.<span style=\"white-space:pre\">	</span>Anda berada di menu Home</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon browser/dunia seperti gambar berikut ini:&nbsp;&nbsp;<img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 55px;\"></p><p>3.<span style=\"white-space:pre\">	</span>Pilih salah satu game yang kamu mainkan</p><p>4.<span style=\"white-space:pre\">	</span>Kemudian klik menu HoYo Guides</p><p>5.<span style=\"white-space:pre\">	</span>Setelah itu, pilih menu Kotak Fitur</p><p>6.<span style=\"white-space:pre\">	</span>Dan Pilih Absen Harian&nbsp; atau dengan nama sejenisnya</p><p>7.<span style=\"white-space:pre\">	</span>Dan Selesaikan Absen Harian dengan pilih bagian yang tunjukkan</p><p>8.<span style=\"white-space:pre\">	</span>Selesai</p><div><br></div>', 11, '2025-06-07 05:52:17'),
(8, 'Peta Interaktif', '<p>1.<span style=\"white-space:pre\">	</span>Membuka aplikasi HoYoLAB</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon browser/dunia seperti gambar berikut ini :&nbsp;<img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 40px;\"></p><p>3.<span style=\"white-space:pre\">	</span>Pilih salah satu game yang kamu mainkan (Genshin Impact/Honkai Star Rail)</p><p>4.<span style=\"white-space:pre\">	</span>Kemudian klik menu HoYo Guides</p><p>5.<span style=\"white-space:pre\">	</span>Setelah itu, pilih menu Kotak Fitur</p><p>6.<span style=\"white-space:pre\">	</span>Dan Pilih Peta Interaktif atau dengan nama sejenisnya</p><p>7.<span style=\"white-space:pre\">	</span>Tunggu Loadingnya selesai, jika ada tutorial, kamu ikutin saja, dan juga pilih server gamemu dan lajut oke itu jika kamu baru pertama kali membukanya,</p><p>8.<span style=\"white-space:pre\">	</span>Jika Sudah pernah maka kamu hanya sampai tunggu selesai loadingnya saja</p><p>9.<span style=\"white-space:pre\">	</span>Selesai</p><p><br></p>', 11, '2025-06-07 05:53:25'),
(9, 'Membuka Halaman Resmi (Postingan Official)', '<p>1.<span style=\"white-space:pre\">	</span>Membuka aplikasi HoYoLAB</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon browser/dunia seperti gambar berikut ini :&nbsp;<img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 40px;\"></p><p>3.<span style=\"white-space:pre\">	</span>Pilih salah satu game yang kamu mainkan</p><p>4.<span style=\"white-space:pre\">	</span>Kemudian klik menu HoYo Guides</p><p>5.<span style=\"white-space:pre\">	</span>Setelah itu, pilih menu Kotak Fitur</p><p>6.<span style=\"white-space:pre\">	</span>Kemudian kamu scroll ke bawah sampai jumpa nama “Resmi” atau dengan nama sejenisnya pada bagian halaman konten.</p><p>7.<span style=\"white-space:pre\">	</span>Tunggu Loadingnya selesai, dan Pilih Postingan paling atas atau terbaru.</p><p>8.<span style=\"white-space:pre\">	</span>Selesai</p>', 11, '2025-06-07 05:54:18'),
(10, 'Halaman Wallpaper', '<p>1.<span style=\"white-space:pre\">	</span>Membuka aplikasi HoYoLAB</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon browser/dunia seperti gambar berikut ini&nbsp; <img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 40px;\">&nbsp; pada menu navigasi bawah.</p><p>3.<span style=\"white-space:pre\">	</span>Pilih salah satu game yang kamu mainkan</p><p>4.<span style=\"white-space:pre\">	</span>Kemudian klik menu HoYo Guides</p><p>5.<span style=\"white-space:pre\">	</span>Setelah itu, pilih menu Kotak Fitur</p><p>6.<span style=\"white-space:pre\">	</span>Kemudian kamu scroll ke bawah sampai jumpa nama “Wallaper” atau dengan nama sejenisnya pada bagian halaman konten, jika tidak ada maka langsung selesai.</p><p>7.<span style=\"white-space:pre\">	</span>Tunggu Loadingnya selesai, dan Pilih Postingan paling atas atau terbaru.</p><p>8.<span style=\"white-space:pre\">	</span>Selesai</p>', 11, '2025-06-07 05:55:21'),
(11, 'Halaman Profile Pengguna/Battle Chronicles', '<p>1.<span style=\"white-space:pre\">	</span>Membuka aplikasi HoYoLAB</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon HoYoLAB “<img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 58px;\"> ”sebagai profile pada menu navigasi bawah.</p><p>3.<span style=\"white-space:pre\">	</span>Selanjutnya, Anda pilih salah satu riwayat atau profile game yang pernah kamu mainkan.</p><p>4.<span style=\"white-space:pre\">	</span>Tunggu selesai loadingnya,&nbsp; sampai tampil kontennya</p><p>5.<span style=\"white-space:pre\">	</span>Selesai</p>', 11, '2025-06-07 05:56:02'),
(12, 'HoyoWiki', '<p>1.<span style=\"white-space:pre\">	</span>Membuka aplikasi HoYoLAB</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon browser/dunia seperti gambar berikut ini&nbsp;&nbsp;<img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 40px;\"></p><p>3.<span style=\"white-space:pre\">	</span>Pilih salah satu game yang kamu mainkan</p><p>4.<span style=\"white-space:pre\">	</span>Kemudian klik menu HoYo Guides</p><p>5.<span style=\"white-space:pre\">	</span>Setelah itu, pilih menu Kotak Fitur</p><p>6.<span style=\"white-space:pre\">	</span>Kemudian kamu scroll ke bawah sampai jumpa nama “HoYoWiki, jika tidak ada maka langsung selesai.</p><p>7.<span style=\"white-space:pre\">	</span>Tunggu Loadingnya selesai, dan Pilih Postingan paling atas atau terbaru.</p><p>8.<span style=\"white-space:pre\">	</span>Selesai</p><div><br></div>', 11, '2025-06-07 05:56:48'),
(13, 'Buat sebuah postingan artikel', '<p>1.<span style=\"white-space:pre\">	</span>Membuka aplikasi HoYoLAB</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon tambah&nbsp; &nbsp;yang berada di tengah menu navigasi bawah \"<img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 59px;\">\"</p><p>3.<span style=\"white-space:pre\">	</span>Selanjutnya Anda pilih konten pada bagian Posting.</p><p>4.<span style=\"white-space:pre\">	</span>Kemudian isi judul dan isi kontennya, dengan kata-kata seperti berikut: “Ini ada postingan pertamaku”.</p><p>5.<span style=\"white-space:pre\">	</span>Kemudian, Anda pilih tombol berikutnya yang berada di atas kanan layar</p><p>6.<span style=\"white-space:pre\">	</span>Kemudian, kamu pilih mau di posting pada kategori game mana, sesuaikan dengan game yang kamu mainkan, saran saya pilih yang sering di mainkan saja.</p><p>7.<span style=\"white-space:pre\">	</span>Kemudian tekan tombol posting dan Selesai</p><div><br></div>', 11, '2025-06-07 05:57:40'),
(14, 'Logout', '<p>1. Membuka aplikasi HoYoLAB</p><p>2.<span style=\"white-space:pre\">	</span>Kemudian Anda pilih icon HoYoLAB “ <img src=\"data:image/png;base64,\" data-filename=\"image.png\" style=\"width: 58px;\">”sebagai profile pada menu navigasi bawah.</p><p>3.<span style=\"white-space:pre\">	</span>Selanjutnya Anda pilih icon gear/pengaturan pada bagian atas kanan layar</p><p>4.<span style=\"white-space:pre\">	</span>Kemudian kamu scroll kebawah sampai muncul tombol logout.</p><p>5.<span style=\"white-space:pre\">	</span>Terakhir kamu, klik tombol logout dan selesaikan proses logout sampai benar2 logout.</p><p>6.<span style=\"white-space:pre\">	</span>Selesai</p>', 11, '2025-06-07 04:56:52'),
(42, 'Login', '<ol><li>Buka Aplikasi Hoyolabbb melalui website</li><li>Pilih metode yang biasa kamu gunakan</li><li>Centang kotak persetujuan</li><li>Selesai</li></ol>', 29, '2025-07-28 23:14:10');
